[15 Regression] ICE in verify_ctor_sanity with -std=c++20 -O1 and no_unique_address sincer15-9189
```
struct non_trivial_if {
  constexpr non_trivial_if() {}
};
struct allocator : non_trivial_if {};
struct padding {};
struct __short {
  [[no_unique_address]] padding p;
};
struct basic_string {
  union {
    __short s;
    int l;
  };
  [[no_unique_address]] allocator a;
  constexpr basic_string() {}
  ~basic_string();
};
struct time_zone {
  basic_string __abbrev;
  long __offset;
};
time_zone convert_to_time_zone() { return {}; }
```

The code above crashes GCC when compiling with `-std=c++23 -O1` (Godbolt:https://godbolt.org/z/xnEx8E7nc). This is a reduced test-case from libc++.
